{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Aromatherapy Membership &amp; Blends</title>
  <meta name="description" content="Calming aromatherapy membership and safe, crafted blends. Memberships, kits, and guidance for mindful scenting." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="site zen">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="main-nav">
        <button class="nav-toggle" id="nav-toggle" aria-expanded="false">Menu</button>
        <ul class="nav-list" id="nav-list">
          <li><a href="index.html">Home</a></li>
          <li><a href="services.html">Offerings</a></li>
          <li><a href="blends.html">Blends</a></li>
          <li><a href="shop.html">Boutique</a></li>
          <li><a href="pricing.html">Plans</a></li>
          <li><a href="about.html">Our Story</a></li>
          <li><a href="book.html">Book</a></li>
          <li><a href="contact.html">Connect</a></li>
        </ul>
      </nav>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero" id="hero" role="region" aria-label="Welcome">
      <div class="pattern"></div>
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="title">Scent as a Pause: Gentle Aromatherapy for Everyday Ritual</h1>
          <p class="subtitle">{{TAGLINE}}</p>
          <p class="lead">Join a small-membership of mindful scent-lovers. Receive seasonal blends, safe-use guides, and monthly live scent sessions led by {{PRACTITIONER_NAME}}.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="pricing.html">See Plans</a>
          </div>
          <p class="safety">Safety note: Our guidance emphasizes dilution, patch testing, and non-medical wellbeing rituals. Not a substitute for professional medical advice.</p>
        </div>
        <div class="hero-card">
          <div class="card">
            <h3>New Member Welcome</h3>
            <p>Starter kit + orientation call. Locals in {{CITY}}, {{STATE}} can request in-person pickup.</p>
            <p class="muted">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
          </div>
        </div>
      </div>
    </section>

    <!-- Story -->
    <section class="story wrap" id="story">
      <div class="story-grid">
        <div class="story-text">
          <h2>Why scent? A warm invitation</h2>
          <p>My path to aromatherapy began with a single lavender sachet and a desire to craft calm moments. I learned to blend thoughtfully, to prioritize safety, and to listen—first to plants, then to people. Today I offer a membership that centers education, ethical sourcing, and ritual-making.</p>
          <p class="muted">Every blend shared here includes notes, recommended dilutions, and guidance for patch testing. We avoid medical claims and focus on supportive experiences.</p>
        </div>
        <div class="story-visual">
          <svg viewBox="0 0 200 160" xmlns="http://www.w3.org/2000/svg" class="illustration" aria-hidden="true">
            <defs>
              <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#E8F6F1"/><stop offset="1" stop-color="#F6F1FF"/></linearGradient>
            </defs>
            <rect width="100%" height="100%" rx="12" fill="url(#g1)"/>
            <g transform="translate(20,20)" fill="#6B5EAE">
              <ellipse cx="60" cy="30" rx="40" ry="18" fill-opacity="0.12"/>
              <path d="M10 90 Q60 10 110 90" stroke="#6B5EAE" stroke-width="2" fill="none" stroke-linecap="round"/>
              <circle cx="30" cy="50" r="6" />
              <circle cx="80" cy="55" r="8" />
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- Framework -->
    <section class="framework wrap" id="framework">
      <h2>A S.A.F.E. Framework for scent</h2>
      <p class="lead">A simple checklist we teach to keep aromatic practice pleasant and considerate.</p>
      <div class="grid cards">
        <div class="card">
          <h3>Sanitize &amp; Source</h3>
          <p>Use clean vessels and ethically sourced essential oils. Know purity and supplier practices.</p>
        </div>
        <div class="card">
          <h3>Always Dilute</h3>
          <p>We recommend conservative dilution ranges and provide specific ratios. Never apply undiluted essential oils to skin.</p>
        </div>
        <div class="card">
          <h3>Feel-Test (Patch)</h3>
          <p>Patch-test blends on a small area; wait 24 hours. Discontinue if irritation occurs.</p>
        </div>
        <div class="card">
          <h3>Ear &amp; Environmental Care</h3>
          <p>Be mindful around children, pets, pregnant people, and those with respiratory sensitivities. Consult your healthcare provider for specific concerns.</p>
        </div>
      </div>
    </section>

    <!-- Offers (Membership focus) -->
    <section class="offers wrap" id="offers">
      <h2>Membership: A seasonal ritual</h2>
      <p>Our membership is designed as a guided practice—monthly themed blends, safety guides, and a members-only session each month.</p>
      <div class="grid offer-cards">
        <div class="card">
          <h3>Foundations</h3>
          <p>Monthly blend, community guide, 10% shop discount.</p>
        </div>
        <div class="card">
          <h3>Ritual</h3>
          <p>Everything in Foundations + quarterly mini-kit and a live workshop.</p>
        </div>
        <div class="card emphasize">
          <h3>Practice</h3>
          <p>All Ritual benefits + one private consult per year and priority bookings.</p>
        </div>
      </div>
      <p class="muted">Members can pause or cancel anytime. We communicate dilution and safety details with each delivery.</p>
    </section>

    <!-- Pricing preview -->
    <section class="pricing-preview wrap" id="pricing">
      <h2>Plans &amp; pricing</h2>
      <div class="grid prices">
        <div class="price-card">
          <h3>Monthly</h3>
          <div class="price">$14 <span class="per">/ month</span></div>
          <p>Flexible monthly membership. Starter kit available separately.</p>
          <a class="btn" href="pricing.html">Choose Monthly</a>
        </div>
        <div class="price-card highlight">
          <h3>Annual</h3>
          <div class="price">$140 <span class="per">/ year</span></div>
          <p>Save two months. Includes a welcome kit and priority booking.</p>
          <a class="btn primary" href="pricing.html">Choose Annual</a>
        </div>
      </div>
      <p class="muted">All plans include safety notes, suggested dilutions, and patch-test instructions.</p>
    </section>

    <!-- Testimonials -->
    <section class="testimonials wrap" id="testimonials">
      <h2>Stories from members</h2>
      <div class="grid quotes">
        <blockquote class="quote">
          "The monthly blends feel like a gentle friend—simple and steady. I learned to dilute properly and love the ritual guidance."<cite>— A. in {{CITY}}</cite>
        </blockquote>
        <blockquote class="quote">
          "{{PRACTITIONER_NAME}} was patient and clear about safety. The starter kit made learning approachable."<cite>— M. in {{STATE}}</cite>
        </blockquote>
        <blockquote class="quote">
          "I ordered a roll-on from the shop for sleep; clear instructions helped me use it safely around my cat."<cite>— L.</cite>
        </blockquote>
      </div>
    </section>

    <!-- Call to action -->
    <section class="cta wrap" id="final-cta">
      <div class="cta-card">
        <h2>Begin a season of mindful scent</h2>
        <p>Join our membership to receive curated blends, safety-first guidance, and a welcoming community.</p>
        <div class="cta-actions">
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="about.html">Meet {{PRACTITIONER_NAME}}</a>
        </div>
        <p class="muted">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">Aromatherapy practice rooted in safety and ritual. Serving {{CITY}}, {{STATE}}.</p>
      </div>
      <div>
        <nav class="foot-nav">
          <a href="blends.html">Blends</a>
          <a href="shop.html">Shop</a>
          <a href="book.html">Book</a>
          <a href="contact.html">Contact</a>
        </nav>
      </div>
      <div>
        <p class="muted">© <span id="year"></span> {{BUSINESS_NAME}}</p>
        <p class="muted">Designed with quiet care.</p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
