{"path":"assets/css/styles.css","content":"/* Zen Minimal Aromatherapy styles */
:root{
  --bg:#FBFCFB;
  --muted:#6C6C76;
  --accent:#6B5EAE;
  --accent-2:#6EC5C5;
  --card:#FFFFFF;
  --glass: rgba(255,255,255,0.6);
  --radius:12px;
  --max:1100px;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:linear-gradient(180deg,var(--bg),#F7F6FF 80%);color:#222;line-height:1.5}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.site-header{background:transparent;padding:18px 0;position:sticky;top:0;z-index:40}
.site-header .wrap{display:flex;align-items:center;gap:18px}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.05rem}
.nav{margin-left:auto}
.nav-toggle{display:none;background:none;border:1px solid transparent;padding:8px 10px;border-radius:8px}
.nav-list{display:flex;gap:14px;list-style:none;margin:0;padding:0}
.nav-list a{color:var(--muted);text-decoration:none;padding:8px;border-radius:8px}
.nav-list a:hover{background:var(--glass)}
.cta{margin-left:14px;padding:8px 12px;border-radius:10px;background:transparent;border:1px solid var(--accent);color:var(--accent);text-decoration:none}
.hero{position:relative;padding:48px 0}
.pattern{position:absolute;inset:0;opacity:0.18;background-image:url('assets/img/pattern.svg');background-repeat:repeat;background-size:320px;mix-blend-mode:multiply;pointer-events:none}
.hero-inner{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:center}
.title{font-size:clamp(1.6rem,3vw,2.4rem);margin:0;color:#222}
.subtitle{color:var(--accent);margin:8px 0 16px}
.lead{margin:0 0 18px;color:var(--muted)}
.hero-ctas .btn{display:inline-block;margin-right:10px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;border:1px solid transparent;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white}
.btn.ghost{background:transparent;border:1px solid rgba(0,0,0,0.06)}
.btn.large{padding:14px 20px;font-size:1.02rem}
.hero-card .card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 6px 18px rgba(106,94,174,0.06)}
.safety{font-size:0.85rem;color:var(--muted);margin-top:14px}
.story{padding:36px 0}
.story-grid{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:center}
.illustration{width:100%;height:auto;border-radius:10px}
.framework{padding:36px 0}
.grid{display:grid;gap:16px}
.grid.cards{grid-template-columns:repeat(2,minmax(0,1fr))}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(0,0,0,0.04)}
.card.emphasize{border:1px solid rgba(107,94,174,0.08)}
.offers .offer-cards{grid-template-columns:repeat(3,minmax(0,1fr))}
.pricing-preview{padding:36px 0}
.grid.prices{grid-template-columns:1fr 1fr;align-items:start}
.price-card{background:linear-gradient(180deg,#FFFFFF, #FEFFFF);padding:20px;border-radius:12px;box-shadow:0 6px 24px rgba(105,95,170,0.05)}
.price-card.highlight{border:1px solid rgba(107,94,174,0.08)}
.price{font-size:1.5rem;font-weight:700;color:var(--accent);margin:10px 0}
.testimonials{padding:36px 0}
.grid.quotes{grid-template-columns:repeat(3,1fr)}
.quote{background:linear-gradient(180deg,#fff,#fbfbff);padding:16px;border-radius:12px;font-style:italic}
.cta-card{background:linear-gradient(180deg,#FFFFFF,#F8FBFA);padding:28px;border-radius:14px;text-align:center}
.footer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;padding:24px 0}
.muted{color:var(--muted);font-size:0.95rem}
@media(max-width:900px){
  .hero-inner,.story-grid{grid-template-columns:1fr}
  .grid.cards{grid-template-columns:1fr}
  .offered{display:none}
  .nav-list{display:none;position:absolute;right:20px;top:64px;background:var(--card);padding:10px;border-radius:10px;box-shadow:0 10px 30px rgba(0,0,0,0.08)}
  .nav-toggle{display:inline-block}
  .grid.quotes{grid-template-columns:1fr}
  .wrap{padding:18px}
}
/* subtle micro interactions */
a.btn{transition:transform .15s ease,box-shadow .15s ease}
a.btn:hover{transform:translateY(-3px)}
.card, .price-card{transition:transform .18s ease}
.card:hover{transform:translateY(-6px)}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  var toggle = document.getElementById('nav-toggle');
  var list = document.getElementById('nav-list');
  if(toggle){
    toggle.addEventListener('click',function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', (!expanded).toString());
      if(list.style.display === 'block') list.style.display = '';
      else list.style.display = 'block';
    });
  }

  // Insert current year
  var y = new Date().getFullYear();
  var el = document.getElementById('year');
  if(el) el.textContent = y;

  // Smooth scroll for internal links
  document.addEventListener('click', function(e){
    var a = e.target.closest('a');
    if(!a) return;
    var href = a.getAttribute('href')||'';
    if(href.indexOf('#')===0){
      e.preventDefault();
      var target = document.querySelector(href);
      if(target) target.scrollIntoView({behavior:'smooth'});
    }
  });

  // Small accessibility enhancement: focus outlines for keyboard users
  function handleFirstTab(e){
    if(e.key === 'Tab'){
      document.body.classList.add('user-is-tabbing');
      window.removeEventListener('keydown', handleFirstTab);
    }
  }
  window.addEventListener('keydown', handleFirstTab);
})();
"} 
